1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"fmt"
7		"os"
8		"strconv"
9		"unicode/utf8"
10	)
11	
12	// EvalReason is the machine-readable outcome of a flag evaluation.
13	type EvalReason string
14	
15	const (
16		EvalDisabled EvalReason = "disabled"
17		EvalRule     EvalReason = "rule"
18		EvalDefault  EvalReason = "default"
19	)
20	
21	// Condition is one predicate over an evaluation context.
22	type Condition struct {
23		Attribute string
24		Op        string
25		// strVal 用于 eq；inVal 用于 in（至少一项）。
26		strVal string
27		inVal  []string
28	}
29	
30	// Rule groups conditions that must all hold; on match the flag takes Value.
31	type Rule struct {
32		ID         string
33		Value      bool
34		Conditions []Condition
35	}
36	
37	// Flag is one feature toggle with its default and ordered rules.
38	type Flag struct {
39		Key     string
40		Enabled bool
41		Default bool
42		Rules   []Rule
43	}
44	
45	// Config is a validated feature flag configuration.
46	type Config struct {
47		Flags []Flag
48	}
49	
50	// EvalResult is the deterministic outcome of evaluating one flag.
51	type EvalResult struct {
52		Key    string     `json:"key"`
53		Value  bool       `json:"value"`
54		Reason EvalReason `json:"reason"`
55		RuleID *string    `json:"ruleId"`
56	}
57	
58	// Equals reports whether two evaluation results are identical.
59	func (r EvalResult) Equals(other EvalResult) bool {
60		if r.Key != other.Key || r.Value != other.Value || r.Reason != other.Reason {
61			return false
62		}
63		if (r.RuleID == nil) != (other.RuleID == nil) {
64			return false
65		}
66		if r.RuleID != nil && *r.RuleID != *other.RuleID {
67			return false
68		}
69		return true
70	}
71	
72	// Context is a validated map of attribute names to string values.
73	type Context struct {
74		values map[string]string
75	}
76	
77	// LoadConfig reads and strictly validates a UTF-8 JSON flag config file.
78	// 所有开关都会被完整校验，包括不会被求值或已关闭的开关。
79	func LoadConfig(path string) (*Config, error) {
80		raw, err := os.ReadFile(path)
81		if err != nil {
82			return nil, fmt.Errorf("cannot read config file %q: %w", path, err)
83		}
84		return ParseConfig(raw)
85	}
86	
87	// LoadContext reads and validates a UTF-8 JSON context file.
88	func LoadContext(path string) (*Context, error) {
89		raw, err := os.ReadFile(path)
90		if err != nil {
91			return nil, fmt.Errorf("cannot read context file %q: %w", path, err)
92		}
93		return ParseContext(raw)
94	}
95	
96	// ParseConfig parses a config document from JSON bytes with strict typing.
97	// 先解析到 any 再逐字段校验，以区分“字段缺失”与“显式提供的 false”。
98	func ParseConfig(raw []byte) (*Config, error) {
99		if !utf8.Valid(raw) {
100			return nil, fmt.Errorf("config: file is not valid UTF-8")
101		}
102		if err := rejectInvalidUnicodeEscapes(raw, "config"); err != nil {
103			return nil, err
104		}
105		if err := rejectDuplicateFields(raw, "config"); err != nil {
106			return nil, err
107		}
108		var doc any
109		if err := json.Unmarshal(raw, &doc); err != nil {
110			return nil, fmt.Errorf("config: invalid JSON: %w", err)
111		}
112		root, ok := doc.(map[string]any)
113		if !ok {
114			return nil, fmt.Errorf("config: top level must be a JSON object")
115		}
116		flagsRaw, present := root["flags"]
117		if !present {
118			return nil, fmt.Errorf("config.flags: field is required")
119		}
120		if flagsRaw == nil {
121			return nil, fmt.Errorf("config.flags: must be an array, got null")
122		}
123		flagsArr, ok := flagsRaw.([]any)
124		if !ok {
125			return nil, fmt.Errorf("config.flags: must be an array")
126		}
127		cfg := &Config{}
128		seenKeys := map[string]int{}
129		for i, fr := range flagsArr {
130			flag, err := parseFlag(fr, i)
131			if err != nil {
132				return nil, err
133			}
134			if prev, dup := seenKeys[flag.Key]; dup {
135				return nil, fmt.Errorf("config.flags[%d].key: duplicate flag key %q (first at flags[%d])", i, flag.Key, prev)
136			}
137			seenKeys[flag.Key] = i
138			cfg.Flags = append(cfg.Flags, flag)
139		}
140		return cfg, nil
141	}
142	
143	// ParseContext parses an attribute-name -> string context object; it may be empty.
144	func ParseContext(raw []byte) (*Context, error) {
145		if !utf8.Valid(raw) {
146			return nil, fmt.Errorf("context: file is not valid UTF-8")
147		}
148		if err := rejectInvalidUnicodeEscapes(raw, "context"); err != nil {
149			return nil, err
150		}
151		if err := rejectDuplicateFields(raw, "context"); err != nil {
152			return nil, err
153		}
154		var doc any
155		if err := json.Unmarshal(raw, &doc); err != nil {
156			return nil, fmt.Errorf("context: invalid JSON: %w", err)
157		}
158		root, ok := doc.(map[string]any)
159		if !ok {
160			return nil, fmt.Errorf("context: top level must be a JSON object")
161		}
162		// 值类型必须按原文顺序逐个判定：Go map 的遍历顺序不稳定，不能直接
163		// range root，否则同一文件在不同运行中可能报告不同属性。对象或数组
164		// 值整体算所属顶层属性的一个值，错误不指向其内部成员。
165		if err := checkContextValueTypes(raw); err != nil {
166			return nil, err
167		}
168		ctx := &Context{values: make(map[string]string, len(root))}
169		for k, v := range root {
170			ctx.values[k] = v.(string)
171		}
172		return ctx, nil
173	}
174	
175	// checkContextValueTypes 按文件原文顺序扫描已通过语法与重复字段检查的
176	// context 对象，报告第一个值不是字符串的顶层属性。键名使用解码后的文字
177	// （合法的 \uXXXX 转义与直接字符同义；大小写与空白按原样保留）。嵌套
178	// 对象或数组整体跳过，其内部成员不单独检查。
179	func checkContextValueTypes(raw []byte) error {
180		dec := json.NewDecoder(bytes.NewReader(raw))
181		// 第一个令牌必须是顶层对象的 '{'；非对象的情形在 ParseContext 中报告。
182		if tok, err := dec.Token(); err != nil || tok != json.Delim('{') {
183			return nil
184		}
185		for dec.More() {
186			keyTok, err := dec.Token()
187			if err != nil {
188				return nil // 语法错误留给 Unmarshal 的报错
189			}
190			key, _ := keyTok.(string)
191			var value any
192			if err := dec.Decode(&value); err != nil {
193				return nil
194			}
195			if _, ok := value.(string); !ok {
196				return fmt.Errorf("context.%s: value must be a string", key)
197			}
198		}
199		return nil
200	}
201	
202	// Get looks up an attribute; an empty string is a legal value.
203	func (c *Context) Get(attribute string) (string, bool) {
204		if c == nil {
205			return "", false
206		}
207		v, ok := c.values[attribute]
208		return v, ok
209	}
210	
211	// Find returns the flag with the given key, or nil if absent.
212	func (c *Config) Find(key string) *Flag {
213		if c == nil {
214			return nil
215		}
216		for i := range c.Flags {
217			if c.Flags[i].Key == key {
218				return &c.Flags[i]
219			}
220		}
221		return nil
222	}
223	
224	// Evaluate deterministically evaluates a flag against a context.
225	// 未启用固定 false（reason=disabled），不使用默认值或规则；启用后取首条
226	// 所有条件均成立的规则的 value；无匹配取 default。求值不依赖时间、随机数
227	// 或 map 遍历顺序，同一配置与上下文重复求值结果一致。
228	func (f *Flag) Evaluate(ctx *Context) EvalResult {
229		if !f.Enabled {
230			return EvalResult{Key: f.Key, Value: false, Reason: EvalDisabled, RuleID: nil}
231		}
232		for i := range f.Rules {
233			rule := &f.Rules[i]
234			if rule.matches(ctx) {
235				id := rule.ID
236				return EvalResult{Key: f.Key, Value: rule.Value, Reason: EvalRule, RuleID: &id}
237			}
238		}
239		return EvalResult{Key: f.Key, Value: f.Default, Reason: EvalDefault, RuleID: nil}
240	}
241	
242	func (r *Rule) matches(ctx *Context) bool {
243		for i := range r.Conditions {
244			if !r.Conditions[i].matches(ctx) {
245				return false
246			}
247		}
248		return true
249	}
250	
251	func (c Condition) matches(ctx *Context) bool {
252		v, present := ctx.Get(c.Attribute)
253		if !present {
254			return false
255		}
256		switch c.Op {
257		case "eq":
258			return v == c.strVal
259		case "in":
260			for _, candidate := range c.inVal {
261				if v == candidate {
262					return true
263				}
264			}
265			return false
266		default:
267			// 解析阶段已拒绝未知运算符，防御性处理。
268			return false
269		}
270	}
271	
272	// MarshalResult renders the result as a single compact JSON object.
273	func MarshalResult(r EvalResult) ([]byte, error) {
274		var buf bytes.Buffer
275		enc := json.NewEncoder(&buf)
276		enc.SetEscapeHTML(false)
277		if err := enc.Encode(r); err != nil {
278			return nil, err
279		}
280		return bytes.TrimRight(buf.Bytes(), "\n"), nil
281	}
282	
283	// --- strict parsing helpers -------------------------------------------------
284	
285	// jsonFrame 是 JSON 原文遍历中一个对象或数组的层级状态。重复字段检查与非法
286	// Unicode 转义检查共用这一份层级与位置定义，调整错误定位时只需改这一处。
287	type jsonFrame struct {
288		path   string // 容器自身的完整位置，如 config.flags[0].rules[1]
289		object bool
290		// keys 记录本对象已声明的字段名（按解码后的字符串），仅重复字段检查使用；
291		// Unicode 遍历不登记字段，保持 nil。
292		keys map[string]struct{}
293		// lastKey 是对象最近一个字段名，用于拼出字段值的位置。
294		lastKey string
295		// expectKey 标记对象内下一个字符串是否为字段名。
296		expectKey bool
297		// nextIndex 是数组下一个元素的下标。
298		nextIndex int
299	}
300	
301	// jsonPathTracker 是两类 JSON 检查共用的对象层级、数组位置与字段路径状态机。
302	// label 是根容器的位置前缀（"config" 或 "context"）。
303	type jsonPathTracker struct {
304		label string
305		stack []*jsonFrame
306	}
307	
308	func newJSONPathTracker(label string) *jsonPathTracker {
309		return &jsonPathTracker{label: label}
310	}
311	
312	func (t *jsonPathTracker) top() *jsonFrame {
313		return t.stack[len(t.stack)-1]
314	}
315	
316	// childPath 拼出栈顶容器内下一个子值的位置：对象的字段值用 .字段名，
317	// 数组元素用 [下标]。
318	func (t *jsonPathTracker) childPath() string {
319		top := t.top()
320		if top.object {
321			return top.path + "." + top.lastKey
322		}
323		return top.path + "[" + strconv.Itoa(top.nextIndex) + "]"
324	}
325	
326	// beginContainer 在遇到 '{' 或 '[' 时压入新容器，返回新容器的完整位置。
327	func (t *jsonPathTracker) beginContainer(object bool) string {
328		path := t.label
329		if len(t.stack) > 0 {
330			path = t.childPath()
331		}
332		t.stack = append(t.stack, &jsonFrame{path: path, object: object, expectKey: object})
333		return path
334	}
335	
336	// endContainer 在遇到 '}' 或 ']' 时弹出容器，并把整个容器计为父容器中
337	// 一个已完成的值。
338	func (t *jsonPathTracker) endContainer() {
339		if len(t.stack) > 0 {
340			t.stack = t.stack[:len(t.stack)-1]
341		}
342		t.endValue()
343	}
344	
345	// atKey 报告下一个字符串是否应按对象字段名处理。
346	func (t *jsonPathTracker) atKey() bool {
347		return len(t.stack) > 0 && t.top().object && t.top().expectKey
348	}
349	
350	// currentPath 返回当前容器自身的位置（字段名报错时指向所属对象）；
351	// 栈为空时返回根标签。
352	func (t *jsonPathTracker) currentPath() string {
353		if len(t.stack) == 0 {
354			return t.label
355		}
356		return t.top().path
357	}
358	
359	// valuePath 拼出下一个字符串值（字段值或数组元素）的位置，但不改变状态。
360	func (t *jsonPathTracker) valuePath() string {
361		if len(t.stack) == 0 {
362			return t.label
363		}
364		return t.childPath()
365	}
366	
367	// endValue 在一个字段值或数组元素完成后调用：对象回到等待字段名的状态，
368	// 数组推进元素下标。
369	func (t *jsonPathTracker) endValue() {
370		if len(t.stack) == 0 {
371			return
372		}
373		top := t.top()
374		if top.object {
375			top.expectKey = true
376		} else {
377			top.nextIndex++
378		}
379	}
380	
381	// noteKey 登记一个已解码的对象字段名：更新字段路径状态，并在同一对象内第二次
382	// 声明同名字段时返回重复字段错误。
383	func (t *jsonPathTracker) noteKey(name string) error {
384		top := t.top()
385		if top.keys == nil {
386			top.keys = make(map[string]struct{})
387		}
388		if _, dup := top.keys[name]; dup {
389			return fmt.Errorf("%s.%s: duplicate field %q", top.path, name, name)
390		}
391		top.keys[name] = struct{}{}
392		top.lastKey = name
393		top.expectKey = false
394		return nil
395	}
396	
397	// setKey 在不做重复检查的遍历（Unicode 扫描）中记录一个成功解码的字段名，
398	// 仅维护字段值路径所需的状态。
399	func (t *jsonPathTracker) setKey(name string) {
400		top := t.top()
401		top.lastKey = name
402		top.expectKey = false
403	}
404	
405	// noteInvalidKey 在字段名无法解码（属于 JSON 语法错误）时仅推进键值状态：
406	// 不覆盖已记录的字段名；语法错误留给后续 Unmarshal 报告。
407	func (t *jsonPathTracker) noteInvalidKey() {
408		t.top().expectKey = false
409	}
410	
411	// rejectDuplicateFields 按文件原文顺序扫描 JSON 令牌流，拒绝任何在同一对象内
412	// 重复声明的字段名。字段名按解码后的字符串比较（"enabled" 与 "énabled"
413	// 同名），大小写不同仍是不同字段，名字中的空白不裁剪。检查覆盖所有对象，
414	// 包括附加字段里嵌套的对象；数组元素不属于这一检查。label 是根对象的位置
415	// 前缀（"config" 或 "context"）。对象层级、数组下标与字段路径由
416	// jsonPathTracker 统一维护。JSON 语法错误不在此报告（令牌流失效即停止），
417	// 留给 Unmarshal。
418	func rejectDuplicateFields(raw []byte, label string) error {
419		dec := json.NewDecoder(bytes.NewReader(raw))
420		tracker := newJSONPathTracker(label)
421		for {
422			tok, err := dec.Token()
423			if err != nil {
424				// io.EOF 或语法错误；语法错误由后续 Unmarshal 报告。
425				break
426			}
427			switch t := tok.(type) {
428			case json.Delim:
429				switch t {
430				case '{':
431					tracker.beginContainer(true)
432				case '[':
433					tracker.beginContainer(false)
434				case '}', ']':
435					tracker.endContainer()
436				}
437			case string:
438				if tracker.atKey() {
439					if err := tracker.noteKey(t); err != nil {
440						return err
441					}
442				} else {
443					tracker.endValue()
444				}
445			default:
446				tracker.endValue()
447			}
448		}
449		return nil
450	}
451	
452	// rejectInvalidUnicodeEscapes 按文件原文顺序扫描 JSON 文本，拒绝任何不能组成
453	// 完整字符的 \uXXXX 转义：孤立的高代理项、孤立的低代理项，以及不完整或顺序
454	// 错误的代理项对。encoding/json 解码时会把这类转义静默替换为 U+FFFD，使非法
455	// 输入与真正的 "�" 被当作相同字符串参与求值，或让字段名在替换后被误判为重复，
456	// 因此必须在解码前按原文拒绝。检查覆盖字段名与所有字符串值（包括规则的比较值、
457	// in 列表元素以及附加字段里的字符串），一个文件有多个问题时报告原文中最先出现
458	// 的一处。label 是根对象的位置前缀（"config" 或 "context"）。对象层级、数组
459	// 下标与字段路径由 jsonPathTracker 统一维护；JSON 语法错误不在此报告，留给
460	// Unmarshal。
461	func rejectInvalidUnicodeEscapes(raw []byte, label string) error {
462		tracker := newJSONPathTracker(label)
463		i := 0
464		for i < len(raw) {
465			c := raw[i]
466			switch {
467			case c == '{' || c == '[':
468				tracker.beginContainer(c == '{')
469				i++
470			case c == '}' || c == ']':
471				tracker.endContainer()
472				i++
473			case c == '"':
474				end := jsonStringEnd(raw, i)
475				contentEnd := end
476				if contentEnd > i+1 && raw[contentEnd-1] == '"' {
477					contentEnd-- // 去掉右引号；未终止的字符串留给 Unmarshal 报告
478				}
479				content := raw[i+1 : contentEnd]
480				if tracker.atKey() {
481					if bad := findBadUnicodeEscape(content); bad != nil {
482						return fmt.Errorf("%s: field name %q contains invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
483							tracker.currentPath(), string(content), bad.escape, bad.detail)
484					}
485					// 转义已校验合法，解码用于定位路径；失败说明是语法错误，留给 Unmarshal。
486					if name, ok := decodeJSONString(raw[i:end]); ok {
487						tracker.setKey(name)
488					} else {
489						tracker.noteInvalidKey()
490					}
491				} else {
492					path := tracker.valuePath()
493					if bad := findBadUnicodeEscape(content); bad != nil {
494						return fmt.Errorf("%s: invalid Unicode escape %s: Unicode escape does not form a complete character (%s)",
495							path, bad.escape, bad.detail)
496					}
497					tracker.endValue()
498				}
499				i = end
500			case c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == ':' || c == ',':
501				i++
502			default:
503				// 数字与 true/false/null 等标量：跳过至下一个结构字符，按一个值计。
504				for i < len(raw) && !isJSONStructural(raw[i]) {
505					i++
506				}
507				tracker.endValue()
508			}
509		}
510		return nil
511	}
512	
513	// decodeJSONString 解码一个完整的 JSON 字符串字面量（含两侧引号）；ok 为 false
514	// 表示字面量本身非法（未终止或转义写法错误等），属于 JSON 语法错误。
515	func decodeJSONString(lit []byte) (s string, ok bool) {
516		if err := json.Unmarshal(lit, &s); err != nil {
517			return "", false
518		}
519		return s, true
520	}
521	
522	// badEscape 描述一处不能组成完整字符的 \uXXXX 转义。
523	type badEscape struct {
524		escape string // 原文中的转义序列，如 \uD800
525		detail string // 具体问题（孤立高代理项/孤立低代理项）
526	}
527	
528	// jsonStringEnd 返回从 raw[i]（必须是 '"'）开始的字符串字面量结束位置
529	// （右引号之后的下标）；未终止时返回 len(raw)。
530	func jsonStringEnd(raw []byte, i int) int {
531		j := i + 1
532		for j < len(raw) {
533			switch raw[j] {
534			case '\\':
535				j += 2
536			case '"':
537				return j + 1
538			default:
539				j++
540			}
541		}
542		return len(raw)
543	}
544	
545	// findBadUnicodeEscape 在字符串内容（不含引号）中查找第一处不能组成完整
546	// 字符的 \uXXXX 转义；没有则返回 nil。反斜杠本身的转义（\\）先于 \u 判定，
547	// 因此 "\\uD800" 只是普通文本。非法的 \u 写法（非 4 位十六进制）属于 JSON
548	// 语法错误，不在此报告。
549	func findBadUnicodeEscape(content []byte) *badEscape {
550		j := 0
551		for j < len(content) {
552			if content[j] != '\\' {
553				j++
554				continue
555			}
556			if j+1 >= len(content) {
557				break
558			}
559			if content[j+1] != 'u' {
560				j += 2
561				continue
562			}
563			if j+6 > len(content) || !isHex4(content[j+2:j+6]) {
564				j += 2
565				continue
566			}
567			cp := hexVal4(content[j+2 : j+6])
568			switch {
569			case cp >= 0xD800 && cp <= 0xDBFF:
570				// 高代理项只有紧跟一个低代理项转义才组成完整字符。
571				if j+12 <= len(content) && content[j+6] == '\\' && content[j+7] == 'u' &&
572					isHex4(content[j+8:j+12]) {
573					if lo := hexVal4(content[j+8 : j+12]); lo >= 0xDC00 && lo <= 0xDFFF {
574						j += 12
575						continue
576					}
577				}
578				return &badEscape{
579					escape: string(content[j : j+6]),
580					detail: "high surrogate is not followed by a low surrogate",
581				}
582			case cp >= 0xDC00 && cp <= 0xDFFF:
583				return &badEscape{
584					escape: string(content[j : j+6]),
585					detail: "low surrogate is not preceded by a high surrogate",
586				}
587			}
588			j += 6
589		}
590		return nil
591	}
592	
593	// isJSONStructural 报告 b 是否为 JSON 结构字符或空白（标量值的边界）。
594	func isJSONStructural(b byte) bool {
595		switch b {
596		case ' ', '\t', '\n', '\r', '{', '}', '[', ']', ':', ',', '"':
597			return true
598		}
599		return false
600	}
601	
602	// isHex4 报告 b 是否恰好为 4 个十六进制数字。
603	func isHex4(b []byte) bool {
604		if len(b) != 4 {
605			return false
606		}
607		for _, c := range b {
608			if !isHexDigit(c) {
609				return false
610			}
611		}
612		return true
613	}
614	
615	func isHexDigit(c byte) bool {
616		return ('0' <= c && c <= '9') || ('a' <= c && c <= 'f') || ('A' <= c && c <= 'F')
617	}
618	
619	// hexVal4 把 4 个十六进制数字解析为码点值；调用前须先经 isHex4 校验。
620	func hexVal4(b []byte) int {
621		v := 0
622		for _, c := range b {
623			v <<= 4
624			switch {
625			case '0' <= c && c <= '9':
626				v |= int(c - '0')
627			case 'a' <= c && c <= 'f':
628				v |= int(c-'a') + 10
629			default: // 'A' <= c && c <= 'F'
630				v |= int(c-'A') + 10
631			}
632		}
633		return v
634	}
635	
636	func parseFlag(raw any, index int) (Flag, error) {
637		loc := fmt.Sprintf("config.flags[%d]", index)
638		obj, ok := raw.(map[string]any)
639		if !ok {
640			return Flag{}, fmt.Errorf("%s: flag must be a JSON object", loc)
641		}
642		key, err := requireNonEmptyString(obj, "key", loc)
643		if err != nil {
644			return Flag{}, err
645		}
646		enabled, err := requireBool(obj, "enabled", loc)
647		if err != nil {
648			return Flag{}, err
649		}
650		def, err := requireBool(obj, "default", loc)
651		if err != nil {
652			return Flag{}, err
653		}
654		rulesArr, err := requireArrayField(obj, "rules", loc)
655		if err != nil {
656			return Flag{}, err
657		}
658		flag := Flag{Key: key, Enabled: enabled, Default: def}
659		seenRules := map[string]int{}
660		for ri, rv := range rulesArr {
661			rule, err := parseRule(rv, index, ri)
662			if err != nil {
663				return Flag{}, err
664			}
665			if prev, dup := seenRules[rule.ID]; dup {
666				return Flag{}, fmt.Errorf("%s.rules[%d].id: duplicate rule id %q (first at rules[%d])", loc, ri, rule.ID, prev)
667			}
668			seenRules[rule.ID] = ri
669			flag.Rules = append(flag.Rules, rule)
670		}
671		return flag, nil
672	}
673	
674	func parseRule(raw any, flagIndex, ruleIndex int) (Rule, error) {
675		loc := fmt.Sprintf("config.flags[%d].rules[%d]", flagIndex, ruleIndex)
676		obj, ok := raw.(map[string]any)
677		if !ok {
678			return Rule{}, fmt.Errorf("%s: rule must be a JSON object", loc)
679		}
680		id, err := requireNonEmptyString(obj, "id", loc)
681		if err != nil {
682			return Rule{}, err
683		}
684		value, err := requireBool(obj, "value", loc)
685		if err != nil {
686			return Rule{}, err
687		}
688		condsArr, err := requireArrayField(obj, "conditions", loc)
689		if err != nil {
690			return Rule{}, err
691		}
692		if len(condsArr) == 0 {
693			return Rule{}, fmt.Errorf("%s.conditions: must contain at least one condition", loc)
694		}
695		rule := Rule{ID: id, Value: value}
696		for ci, cv := range condsArr {
697			cond, err := parseCondition(cv, flagIndex, ruleIndex, ci)
698			if err != nil {
699				return Rule{}, err
700			}
701			rule.Conditions = append(rule.Conditions, cond)
702		}
703		return rule, nil
704	}
705	
706	func parseCondition(raw any, flagIndex, ruleIndex, condIndex int) (Condition, error) {
707		loc := fmt.Sprintf("config.flags[%d].rules[%d].conditions[%d]", flagIndex, ruleIndex, condIndex)
708		obj, ok := raw.(map[string]any)
709		if !ok {
710			return Condition{}, fmt.Errorf("%s: condition must be a JSON object", loc)
711		}
712		attribute, err := requireNonEmptyString(obj, "attribute", loc)
713		if err != nil {
714			return Condition{}, err
715		}
716		op, err := requireNonEmptyString(obj, "op", loc)
717		if err != nil {
718			return Condition{}, err
719		}
720		valueField, err := requireField(obj, "value", loc)
721		if err != nil {
722			return Condition{}, err
723		}
724		cond := Condition{Attribute: attribute, Op: op}
725		switch op {
726		case "eq":
727			s, ok := valueField.(string)
728			if !ok {
729				return Condition{}, fmt.Errorf("%s.value: must be a string when op is %q", loc, op)
730			}
731			cond.strVal = s
732		case "in":
733			arr, ok := valueField.([]any)
734			if !ok {
735				return Condition{}, fmt.Errorf("%s.value: must be an array when op is %q", loc, op)
736			}
737			if len(arr) == 0 {
738				return Condition{}, fmt.Errorf("%s.value: in-list must contain at least one item", loc)
739			}
740			for ii, item := range arr {
741				s, ok := item.(string)
742				if !ok {
743					return Condition{}, fmt.Errorf("%s.value[%d]: must be a string", loc, ii)
744				}
745				cond.inVal = append(cond.inVal, s)
746			}
747		default:
748			return Condition{}, fmt.Errorf("%s.op: unknown operator %q (allowed: eq, in)", loc, op)
749		}
750		return cond, nil
751	}
752	
753	func requireField(obj map[string]any, name, loc string) (any, error) {
754		v, ok := obj[name]
755		if !ok {
756			return nil, fmt.Errorf("%s.%s: field is required", loc, name)
757		}
758		if v == nil {
759			return nil, fmt.Errorf("%s.%s: must not be null", loc, name)
760		}
761		return v, nil
762	}
763	
764	func requireArrayField(obj map[string]any, name, loc string) ([]any, error) {
765		v, err := requireField(obj, name, loc)
766		if err != nil {
767			return nil, err
768		}
769		arr, ok := v.([]any)
770		if !ok {
771			return nil, fmt.Errorf("%s.%s: must be an array", loc, name)
772		}
773		return arr, nil
774	}
775	
776	func requireNonEmptyString(obj map[string]any, name, loc string) (string, error) {
777		v, err := requireField(obj, name, loc)
778		if err != nil {
779			return "", err
780		}
781		s, ok := v.(string)
782		if !ok {
783			return "", fmt.Errorf("%s.%s: must be a string", loc, name)
784		}
785		if s == "" {
786			return "", fmt.Errorf("%s.%s: must not be empty", loc, name)
787		}
788		return s, nil
789	}
790	
791	func requireBool(obj map[string]any, name, loc string) (bool, error) {
792		v, err := requireField(obj, name, loc)
793		if err != nil {
794			return false, err
795		}
796		b, ok := v.(bool)
797		if !ok {
798			return false, fmt.Errorf("%s.%s: must be a boolean", loc, name)
799		}
800		return b, nil
801	}
802

