506			{"identical values still duplicate", `{"flags":[{"key":"f","enabled":true,"default":false,"default":false,"rules":[]}]}`,
507				`config.flags[0].default`},
508			{"duplicate in extra top-level field", `{"flags":[],"x":1,"x":2}`, `config.x`},
509			{"disabled flag not exempt", `{"flags":[{"key":"f","enabled":false,"enabled":false,"default":false,"rules":[]}]}`,
510				`config.flags[0].enabled`},
511			{"unselected flag not exempt", `{"flags":[
512				{"key":"good","enabled":true,"default":false,"rules":[]},
513				{"key":"bad","enabled":true,"default":false,"default":true,"rules":[]}]}`,
514				`config.flags[1].default`},
515			{"first duplicate in file order wins", `{"flags":[
516				{"key":"f","enabled":true,"default":false,"rules":[]},
517				{"key":"g","enabled":true,"enabled":true,"default":false,"default":false,"rules":[]}]}`,
518				`config.flags[1].enabled`},
519		}
520		for _, tc := range cases {
521			t.Run(tc.name, func(t *testing.T) {
522				_, err := ParseConfig([]byte(tc.raw))
523				if err == nil {
524					t.Fatalf("expected duplicate field error, got nil\nconfig: %s", tc.raw)
525				}
526				if !strings.Contains(err.Error(), "duplicate field") {
527					t.Fatalf("error = %q, want %q wording", err.Error(), "duplicate field")
528				}
529				if !strings.Contains(err.Error(), tc.want) {
530					t.Fatalf("error = %q, want location %q", err.Error(), tc.want)
531				}
532			})
533		}
534	}
