605	func TestInvalidUnicodeEscapesRejected(t *testing.T) {
606		// encoding/json 会把孤立代理项转义静默替换为 U+FFFD；这些输入必须明确失败，
607		// 且错误指出文件（config/context）、字段或数组位置，并说明转义不能组成完整字符。
608		const incomplete = "does not form a complete character"
609		configCases := []struct {
610			name string
611			raw  string
612			want string
613		}{
614			{"eq value lone high surrogate", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
615				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
616				`config.flags[0].rules[0].conditions[0].value`},
617			{"eq value lone low surrogate", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
618				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uDC00"}]}]}]}`,
619				`config.flags[0].rules[0].conditions[0].value`},
620			{"reversed pair", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
621				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uDC00\uD800"}]}]}]}`,
622				`conditions[0].value`},
623			{"high then non-surrogate escape", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
624				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800A"}]}]}]}`,
625				`conditions[0].value`},
626			{"high then high", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
627				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800\uD800"}]}]}]}`,
628				`conditions[0].value`}, {"high at end of string", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
629				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"x\uD800"}]}]}]}`,
630				`conditions[0].value`},
631			{"in-list element", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
632				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"in","value":["ok","\uD800"]}]}]}]}`,
633				`config.flags[0].rules[0].conditions[0].value[1]`},
634			{"flag key string", `{"flags":[{"key":"\uD800","enabled":true,"default":false,"rules":[]}]}`,
635				`config.flags[0].key`},
636			{"extra field value", `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
637				"meta":{"note":"\uDFFF"}}]}`,
638				`config.flags[0].meta.note`},
639			{"disabled flag not exempt", `{"flags":[{"key":"f","enabled":false,"default":false,"rules":[
640				{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
641				`conditions[0].value`},
642			{"unselected flag not exempt", `{"flags":[
643				{"key":"good","enabled":true,"default":false,"rules":[]},
644				{"key":"bad","enabled":true,"default":false,"rules":[
645					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]}]}`,
646				`config.flags[1].rules[0].conditions[0].value`},
647			{"first error in file order wins", `{"flags":[
648				{"key":"f","enabled":true,"default":false,"rules":[
649					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uD800"}]}]},
650				{"key":"g","enabled":true,"default":false,"rules":[
651					{"id":"r","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\uDC00"}]}]}]}`,
652				`config.flags[0].rules[0].conditions[0].value`},
653		}
654		for _, tc := range configCases {
655			t.Run(tc.name, func(t *testing.T) {
656				_, err := ParseConfig([]byte(tc.raw))
657				if err == nil {
658					t.Fatalf("expected invalid Unicode escape error, got nil\nconfig: %s", tc.raw)
659				}
660				if !strings.Contains(err.Error(), incomplete) {
661					t.Fatalf("error = %q, want wording %q", err.Error(), incomplete)
662				}
663				if !strings.Contains(err.Error(), tc.want) {
664					t.Fatalf("error = %q, want location %q", err.Error(), tc.want)
665				}
666			})
667		}
668	
669		// 字段名本身非法：指出所属对象，并保留可辨认的原始转义内容。
670		_, err := ParseConfig([]byte(`{"flags":[{"key":"f","enabled":true,"default":false,"rules":[],
671			"met\uD800a":1}]}`))
672		if err == nil || !strings.Contains(err.Error(), `config.flags[0]`) ||
673			!strings.Contains(err.Error(), `\uD800`) || !strings.Contains(err.Error(), incomplete) {
674			t.Fatalf("bad field name in config: err=%v", err)
675		}
676	
677		// 上下文同样检查值与字段名。
678		_, err = ParseContext([]byte(`{"plan":"\uD800"}`))
679		if err == nil || !strings.Contains(err.Error(), `context.plan`) ||
680			!strings.Contains(err.Error(), incomplete) {
681			t.Fatalf("context value: err=%v", err)
682		}
683		_, err = ParseContext([]byte(`{"pl\uDC00an":"pro"}`))
684		if err == nil || !strings.Contains(err.Error(), `context`) ||
685			!strings.Contains(err.Error(), `\uDC00`) || !strings.Contains(err.Error(), incomplete) {
686			t.Fatalf("context field name: err=%v", err)
687		}
688	}
