690	func TestInvalidUnicodeEscapeNotEquatedWithReplacementChar(t *testing.T) {
691		// 规则要求属性值等于真正的 "�"：上下文提供 "\uD800" 不能在替换后命中规则，
692		// 整个求值必须失败。
693		cfg := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
694			{"id":"r1","value":true,"conditions":[{"attribute":"plan","op":"eq","value":"�"}]}]}]}`
695		if _, err := ParseContext([]byte(`{"plan":"\uD800"}`)); err == nil {
696			t.Fatal("context with lone surrogate must be rejected, not replaced by U+FFFD")
697		}
698		c := mustParseConfig(t, cfg)
699		ctx := mustParseContext(t, `{"plan":"�"}`)
700		if got := c.Find("f").Evaluate(ctx); got.Reason != EvalRule {
701			t.Fatalf("literal U+FFFD still matches: %+v", got)
702		}
703		// 字段名被替换后也不能误报重复字段："\uD800x" 与 "�x" 本不应同名，
704		// 但非法转义必须先于重复字段检查以自身名义报错。
705		_, err := ParseContext([]byte(`{"\uD800x":"a","�x":"b"}`))
706		if err == nil || strings.Contains(err.Error(), "duplicate field") {
707			t.Fatalf("lone surrogate in field name must not surface as duplicate field: %v", err)
708		}
709	}
