711	func TestValidUnicodeEscapesUnchanged(t *testing.T) {
712		// 正确配对的代理项转义与直接写出的同一字符按同一字符串比较。
713		// emojiEsc 是 "😀" 的代理项对转义形式（分两段书写仅为避免源码层面的转义歧义）。
714		emojiEsc := `\uD83D` + `\uDE00`
715		cfgEsc := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
716			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"` + emojiEsc + `"}]}]}]}`
717		if got := eval(t, cfgEsc, "f", `{"emoji":"😀"}`); got.Reason != EvalRule {
718			t.Fatalf("paired escape equals literal: %+v", got)
719		}
720		cfgLit := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
721			{"id":"r1","value":true,"conditions":[{"attribute":"emoji","op":"eq","value":"😀"}]}]}]}`
722		if got := eval(t, cfgLit, "f", `{"emoji":"`+emojiEsc+`"}`); got.Reason != EvalRule {
723			t.Fatalf("literal equals paired escape: %+v", got)
724		}
725		// 真正的 "�" 与 "�" 仍是合法字符串，不能一概禁止替换字符。
726		mustParseContext(t, `{"a":"�","b":"\u`+`FFFD"}`)
727		if got := eval(t, cfgLit, "f", `{"emoji":"�"}`); got.Reason != EvalDefault {
728			t.Fatalf("U+FFFD is just another string: %+v", got)
729		}
730		// 反斜杠转义后的 "\uD800" 是普通文本（内容为 \uD800 六个字符）。
731		mustParseContext(t, `{"a":"\\uD800"}`)
732		cfgText := `{"flags":[{"key":"f","enabled":true,"default":false,"rules":[
733			{"id":"r1","value":true,"conditions":[{"attribute":"a","op":"eq","value":"\\uD800"}]}]}]}`
734		if got := eval(t, cfgText, "f", `{"a":"\\uD800"}`); got.Reason != EvalRule {
735			t.Fatalf("escaped backslash text: %+v", got)
736		}
737	}
