package payflow

import (
	"strings"
	"testing"
)

func TestTmpOversizedNumbers(t *testing.T) {
	bigInt := "1" + strings.Repeat("0", 400)
	typeErr := "value must be a string"
	cases := []struct {
		name string
		raw  string
		want string
	}{
		{"zeta first despite alpha overflow", `{"zeta":false,"alpha":1e400}`, "context.zeta"},
		{"alpha first when reordered", `{"alpha":1e400,"plan":"pro","zeta":false}`, "context.alpha"},
		{"1e400 alone", `{"alpha":1e400}`, "context.alpha"},
		{"-1e400 alone", `{"alpha":-1e400}`, "context.alpha"},
		{"400-zero integer", `{"alpha":` + bigInt + `}`, "context.alpha"},
		{"negative 400-zero integer", `{"alpha":-` + bigInt + `}`, "context.alpha"},
		{"next error after fixing first", `{"zeta":"z","plan":"pro","alpha":1e400}`, "context.alpha"},
		{"overflow inside object points top key", `{"a":"x","obj":{"x":1e400},"b":2}`, "context.obj"},
		{"overflow inside array points top key", `{"arr":[1e400],"later":1}`, "context.arr"},
		{"bool before overflow nested", `{"z":{"x":1e400},"a":[2],"m":true}`, "context.z"},
		{"normal number still type error", `{"a":"ok","b":1}`, "context.b"},
		{"overflow at end earlier bool wins", `{"x":false,"y":1e400}`, "context.x"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			_, err := ParseContext([]byte(tc.raw))
			if err == nil {
				t.Fatalf("expected error, got nil for %s", tc.raw)
			}
			if !strings.Contains(err.Error(), tc.want) || !strings.Contains(err.Error(), typeErr) {
				t.Fatalf("err=%q want location %q and type reason", err.Error(), tc.want)
			}
			if strings.Contains(err.Error(), "invalid JSON") {
				t.Fatalf("must not report invalid JSON: %q", err.Error())
			}
		})
	}

	// Numeric-looking strings are legal and stay strings.
	for _, raw := range []string{`{"a":"1e400"}`, `{"a":"` + bigInt + `"}`} {
		ctx, err := ParseContext([]byte(raw))
		if err != nil {
			t.Fatalf("numeric-looking string must be legal: %s -> %v", raw, err)
		}
		if v, ok := ctx.Get("a"); !ok || !strings.Contains(v, "1") {
			t.Fatalf("string value preserved: %q %v", v, ok)
		}
	}
}

func TestTmpPrecedencePreserved(t *testing.T) {
	// Syntax genuinely broken -> syntax error, even with big number present.
	for _, raw := range []string{
		`{"a":1e400,`,
		`{"a":1e400`,
		`{bad`,
		`{"a":1e400} {}`,
	} {
		_, err := ParseContext([]byte(raw))
		if err == nil || !strings.Contains(err.Error(), "invalid JSON") {
			t.Errorf("syntax: %s -> %v", raw, err)
		}
	}
	// Duplicate field still wins over type error even when a big number is involved.
	if _, err := ParseContext([]byte(`{"b":1e400,"b":2}`)); err == nil ||
		!strings.Contains(err.Error(), "duplicate field") {
		t.Errorf("duplicate precedence: %v", err)
	}
	// Bad unicode escape still wins over earlier type error.
	if _, err := ParseContext([]byte(`{"zeta":false,"plan":"\uD800"}`)); err == nil ||
		!strings.Contains(err.Error(), "does not form a complete character") {
		t.Errorf("unicode precedence: %v", err)
	}
	// Not-an-object stays top-level error.
	if _, err := ParseContext([]byte(`1e400`)); err == nil ||
		!strings.Contains(err.Error(), "top level") {
		t.Errorf("scalar top level: %v", err)
	}
}

func TestTmpConfigOverflowIsTypeError(t *testing.T) {
	// Config: a big number in a typed field reports the field type, not invalid JSON.
	raw := `{"flags":[{"key":"f","enabled":1e400,"default":false,"rules":[]}]}`
	_, err := ParseConfig([]byte(raw))
	if err == nil || !strings.Contains(err.Error(), "flags[0].enabled") {
		t.Errorf("config overflow: %v", err)
	}
	// Big number in flags array itself.
	raw = `{"flags":[1e400]}`
	_, err = ParseConfig([]byte(raw))
	if err == nil || !strings.Contains(err.Error(), "flag must be a JSON object") {
		t.Errorf("config flags array overflow: %v", err)
	}
	// Trailing data in config still rejected.
	_, err = ParseConfig([]byte(`{"flags":[]} x`))
	if err == nil || !strings.Contains(err.Error(), "invalid JSON") {
		t.Errorf("config trailing: %v", err)
	}
}

