package main

import (
	"bytes"
	"encoding/json"
	"fmt"
)

func scan(raw string, useNumber bool) {
	dec := json.NewDecoder(bytes.NewReader([]byte(raw)))
	if useNumber {
		dec.UseNumber()
	}
	for {
		tok, err := dec.Token()
		fmt.Printf("  useNumber=%v tok=%#v err=%v\n", useNumber, tok, err)
		if err != nil {
			break
		}
	}
}

func main() {
	for _, s := range []string{`{"b":1e400,"b":2}`, `{"b":1,"b":2}`} {
		fmt.Println(s)
		scan(s, false)
		scan(s, true)
	}
}
EOF
